import{_ as t,o as d,c as o,ag as a}from"./chunks/framework.HG0H2VLS.js";const p=JSON.parse('{"title":"TableCard — Figma Notes","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/components/TableCard/TableCard.figma-notes.md","filePath":"public/demos/src/components/TableCard/TableCard.figma-notes.md"}'),r={name:"public/demos/src/components/TableCard/TableCard.figma-notes.md"};function s(n,e,i,c,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="tablecard-—-figma-notes" tabindex="-1">TableCard — Figma Notes <a class="header-anchor" href="#tablecard-—-figma-notes" aria-label="Permalink to &quot;TableCard — Figma Notes&quot;">​</a></h1><p><strong>Tier:</strong> Component <strong>Built:</strong> 2026-08-25 (Seating Planner module, wave 3) <strong>Header restructured:</strong> 2026-08-25 — see below <strong>Files:</strong> <code>TableCard.css</code>, <code>TableCard.html</code>, <code>TableCard.figma.ts</code>, <code>TableCard.figma-notes.md</code><strong>Composes:</strong> TableType (<code>.table-type</code>) — tier pill; FullBadge (<code>.full-badge</code>) — at-capacity pill; Button (<code>btn btn--secondary btn--icon btn--2xs</code>) — edit + delete <strong>JS:</strong> none</p><h2 id="figma-node" tabindex="-1">Figma Node <a class="header-anchor" href="#figma-node" aria-label="Permalink to &quot;Figma Node&quot;">​</a></h2><ul><li><strong>File key:</strong> <code>Lus07xi8pPXLN87sQIyrEt</code> (Affino AI — Design System)</li><li><strong>Page:</strong> Seat Planner (<code>3087:5050</code>)</li><li><strong>Component set:</strong> <code>3470:85483</code></li></ul><h2 id="variant-matrix-12-variants" tabindex="-1">Variant matrix (12 variants) <a class="header-anchor" href="#variant-matrix-12-variants" aria-label="Permalink to &quot;Variant matrix (12 variants)&quot;">​</a></h2><p>Axes are <strong>Tier × State × Type × Device</strong>. Tier is single-valued (<code>Component</code>). Device is a media query. <strong>Type produces no CSS at all</strong> — see below. So 12 Figma variants collapse to <strong>one</strong> CSS class plus a media query.</p><table tabindex="0"><thead><tr><th>Type</th><th>State</th><th>Device</th><th>Node</th><th>CSS</th></tr></thead><tbody><tr><td>Empty</td><td>Default</td><td>Desktop</td><td><code>3470:85482</code></td><td><code>.table-card</code></td></tr><tr><td>Empty</td><td>Selected</td><td>Desktop</td><td><code>3470:85481</code></td><td><code>+ .table-card--selected</code></td></tr><tr><td>Populated</td><td>Default</td><td>Desktop</td><td><code>3470:85480</code></td><td><code>.table-card</code></td></tr><tr><td>Populated</td><td>Selected</td><td>Desktop</td><td><code>3470:85479</code></td><td><code>+ .table-card--selected</code></td></tr><tr><td>Full</td><td>Default</td><td>Desktop</td><td><code>3472:85601</code></td><td><code>.table-card</code></td></tr><tr><td>Full</td><td>Selected</td><td>Desktop</td><td><code>3472:85640</code></td><td><code>+ .table-card--selected</code></td></tr><tr><td>Empty</td><td>Default</td><td>Mobile</td><td><code>3484:188877</code></td><td><code>@media (max-width: 767px)</code></td></tr><tr><td>Empty</td><td>Selected</td><td>Mobile</td><td><code>3484:188900</code></td><td>↑ + <code>--selected</code></td></tr><tr><td>Populated</td><td>Default</td><td>Mobile</td><td><code>3484:188923</code></td><td>↑</td></tr><tr><td>Populated</td><td>Selected</td><td>Mobile</td><td><code>3484:189007</code></td><td>↑ + <code>--selected</code></td></tr><tr><td>Full</td><td>Default</td><td>Mobile</td><td><code>3484:188962</code></td><td>↑</td></tr><tr><td>Full</td><td>Selected</td><td>Mobile</td><td><code>3484:189046</code></td><td>↑ + <code>--selected</code></td></tr></tbody></table><p>Desktop: Empty 289×172, Populated/Full 289×185. Mobile: 289×162 / 289×175. (Figma shed 1px when the bar-to-legend gap went 9px → 8px, which the CSS already used.)</p><p>Rendered heights are <strong>177 / 190</strong>, i.e. +5. Three sources: the card&#39;s own 1px border top and bottom; the two rules — Figma draws those as zero-height <code>line</code> nodes with the stroke outside the box, whereas an <code>&lt;hr&gt;</code> with a 1px border is genuinely 1px tall; and 1px on the title row, where a 16px bold line box measures 20px in the browser against Figma&#39;s 19. Cosmetic arithmetic in an auto-height card.</p><h3 id="the-whole-type-axis-is-data-not-css" tabindex="-1">The whole Type axis is data, not CSS <a class="header-anchor" href="#the-whole-type-axis-is-data-not-css" aria-label="Permalink to &quot;The whole Type axis is data, not CSS&quot;">​</a></h3><p>Empty, Populated and Full differ <strong>only</strong> in:</p><ul><li>how many bar segments exist (Empty has one, the others five),</li><li>how many legend rows exist (Empty one, the others two after wrapping),</li><li>whether the FullBadge is present.</li></ul><p>All three are markup the caller supplies. Nothing branches on Type, so there are deliberately <strong>no <code>--empty</code> / <code>--populated</code> / <code>--full</code> modifiers</strong> — empty modifier classes would be dead code. Only State earns CSS. The 13px height difference between Empty and Populated is just the second legend row (11px + the 2px row gap).</p><h3 id="the-bar-in-figma-contradicts-its-own-legend" tabindex="-1">The bar in Figma contradicts its own legend <a class="header-anchor" href="#the-bar-in-figma-contradicts-its-own-legend" aria-label="Permalink to &quot;The bar in Figma contradicts its own legend&quot;">​</a></h3><p>Figma draws the segments at fixed widths — 62 / 31 / 31 / 62 with the empty one <code>flex-1</code> — against a legend reading Attendee 2, VIP 1, Speaker 1, Sponsor 2, Empty 4 of a 10-seat table. Those widths put 6 of 10 seated at <strong>73% of the track</strong>, not 60%. <strong>Never port them.</strong></p><p>Each segment instead carries its seat count in a <code>--seg</code> custom property and divides the track with <code>flex-grow</code> on a zero <code>flex-basis</code>, so the split is exact and the segments always cover the track (which is why the track needs no background of its own — Figma gives it none). Verified: a 2/1/1/2/4 breakdown renders at exactly 20 / 10 / 10 / 20 / 40 %.</p><p>Two further sample-data contradictions in Figma, worth fixing there but not ported:</p><ul><li><strong>Type=Empty</strong> shows <code>Empty (4)</code> beside <code>0 / 10 seated</code>. Should be <code>Empty (10)</code>. The demo uses 10, because shipping a demo that visibly contradicts itself is worse than deviating from broken sample text.</li><li><strong>Type=Full</strong> shows <code>10 / 10 seated</code> and the FULL badge, but keeps Populated&#39;s legend and its grey empty segment. The demo uses a breakdown that actually sums to 10 with nothing empty.</li></ul><h2 id="interaction-model" tabindex="-1">Interaction model <a class="header-anchor" href="#interaction-model" aria-label="Permalink to &quot;Interaction model&quot;">​</a></h2><p>Confirmed with the designer 2026-08-25 — the same contract as RoomCard and AttendeeCard:</p><ul><li><strong>Presentational only.</strong> The parent module owns selection and toggles <code>.table-card--selected</code>. Selecting a table is what opens Table Detail.</li><li><strong>The whole card is the select trigger.</strong> <code>.table-card__select</code> is a real <code>&lt;button&gt;</code> wrapping the table name, with an <code>::after</code> stretched over the card. <code>.table-card__actions</code> is raised on <code>z-index: 1</code> so edit and delete stay independently clickable. Verified by hit-testing: the card&#39;s lower centre resolves to <code>.table-card__select</code>, the edit button&#39;s centre to its own icon. The tier pill needs no raising — it is not interactive, and the overlay is transparent.</li><li><strong>Focus rings the card, not the name</strong>, via <code>.table-card:has(.table-card__select:focus-visible)</code>.</li></ul><h2 id="state-deltas" tabindex="-1">State deltas <a class="header-anchor" href="#state-deltas" aria-label="Permalink to &quot;State deltas&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Background</th><th>Border</th></tr></thead><tbody><tr><td>Default</td><td><code>--ai-surface-primary</code></td><td>1px solid <code>--ai-border-secondary</code></td></tr><tr><td>Selected</td><td><code>--ai-surface-minimal</code></td><td>1px solid <code>--ai-border-brand</code></td></tr></tbody></table><p>Read from the Selected variant&#39;s design context, <strong>not inferred</strong> — <code>get_variable_defs</code> on <code>3470:85479</code> returns <em>both</em> <code>--ai-surface-primary</code> and <code>--ai-surface-minimal</code>, so the variable list alone could not settle which one the card takes.</p><h2 id="device-mobile-deltas" tabindex="-1">Device=Mobile deltas <a class="header-anchor" href="#device-mobile-deltas" aria-label="Permalink to &quot;Device=Mobile deltas&quot;">​</a></h2><p>Two come from Figma (verified against <code>3484:188923</code>); the third is a designer addition.</p><table tabindex="0"><thead><tr><th>Property</th><th>Desktop</th><th>Mobile</th><th>Source</th></tr></thead><tbody><tr><td>card <code>padding</code></td><td><code>--ai-spacing-5</code> (16px)</td><td><code>--ai-spacing-4</code> (12px)</td><td>Figma</td></tr><tr><td>name <code>font-size</code></td><td><code>--ai-font-fixed-sm</code> (16px)</td><td><code>--ai-font-fixed-xs</code> (14px)</td><td>Figma</td></tr><tr><td><code>__sponsor</code> <code>padding-block-start</code></td><td><code>--ai-spacing-2</code> (6px)</td><td><strong><code>--ai-spacing-1</code></strong> (4px)</td><td><strong>designer, 2026-08-25</strong></td></tr></tbody></table><p>Figma keeps the sponsor row&#39;s 6px padding at both breakpoints; it was tightened to 4px on mobile, where the smaller 14px title leaves the row looking loosely attached to it. Measured: the sponsor row goes 22px → 20px and the header 42px → 38px, with desktop untouched.</p><p>Bar, legend, swatches, badge and buttons are identical between breakpoints. Note the <code>min-inline-size</code> stays <code>--ai-size-4</code> (240px) at both — <strong>unlike RoomCard</strong>, whose min-width steps 280 → 240.</p><h2 id="token-mapping" tabindex="-1">Token mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th><th>Role</th></tr></thead><tbody><tr><td><code>--ai-surface-primary</code> / <code>--ai-surface-minimal</code></td><td><code>background-color</code></td><td>per state</td></tr><tr><td><code>--ai-border-secondary</code> / <code>--ai-border-brand</code></td><td><code>border-color</code></td><td>per state</td></tr><tr><td><code>--ai-border-secondary</code></td><td>the two rules</td><td>resolved via <code>get_variable_defs</code> on <code>3470:85258</code></td></tr><tr><td><code>--ai-radius-lg</code></td><td>card <code>border-radius</code> (16px)</td><td></td></tr><tr><td><code>light/shadow-xxs</code> → <code>--ai-shadow-xxs</code></td><td>card <code>box-shadow</code></td><td></td></tr><tr><td><code>--ai-spacing-5</code> / <code>--ai-spacing-4</code></td><td>card <code>padding</code> desktop / mobile</td><td></td></tr><tr><td><code>--ai-spacing-4</code></td><td>card <code>gap</code> (12px)</td><td></td></tr><tr><td><code>--ai-size-4</code></td><td>card <code>min-inline-size</code> (240px, both breakpoints)</td><td></td></tr><tr><td><code>--ai-spacing-0</code></td><td>title-group <code>gap</code> (0)</td><td></td></tr><tr><td><code>--ai-font-fixed-sm</code> / <code>-xs</code></td><td>table name, desktop / mobile</td><td></td></tr><tr><td><code>--ai-spacing-2</code></td><td>sponsor row <code>gap</code> + <code>padding-block-start</code> (6px)</td><td></td></tr><tr><td><code>--ai-icon-size-sm</code></td><td>sponsor icon (16px)</td><td>via <code>get_variable_defs</code> on <code>3476:106260</code></td></tr><tr><td><code>--ai-icon-contrast</code></td><td>sponsor icon colour</td><td>same fetch</td></tr><tr><td><code>--ai-font-fixed-2xs</code></td><td>sponsor name, seated count (12px)</td><td></td></tr><tr><td><code>--ai-leading-xs</code></td><td>sponsor name <code>line-height</code></td><td></td></tr><tr><td><code>--ai-text-primary</code> / <code>--ai-text-contrast</code> / <code>--ai-text-secondary</code></td><td>name / sponsor + legend / count</td><td></td></tr><tr><td><code>--ai-spacing-3</code></td><td>bar <code>block-size</code> (8px), viz <code>gap</code>, legend <code>column-gap</code>, footer count <code>gap</code></td><td></td></tr><tr><td><code>--ai-spacing-px</code></td><td>bar segment <code>gap</code> (1px)</td><td></td></tr><tr><td><code>--ai-radius-sm</code></td><td>bar <code>border-radius</code> (4px)</td><td></td></tr><tr><td><code>--ai-spacing-0-5</code></td><td>legend <code>row-gap</code> (2px)</td><td></td></tr><tr><td><code>--ai-radius-xs</code></td><td>legend swatch <code>border-radius</code> (2px)</td><td><strong>token added for this build</strong></td></tr><tr><td><code>--sp-attendee</code> / <code>--sp-vip</code> / <code>--sp-speaker</code> / <code>--sp-sponsor</code></td><td>bar segments + legend swatches</td><td></td></tr><tr><td><code>--ai-surface-contrast</code></td><td>empty segment + swatch</td><td></td></tr><tr><td><code>--ai-font-fixed-6xs</code></td><td>legend text (9px)</td><td></td></tr><tr><td><code>--ai-font-bold</code> / <code>-medium</code> / <code>-regular</code></td><td>name / sponsor + count / legend</td><td></td></tr><tr><td><code>--ai-spacing-1</code></td><td>legend-item <code>gap</code>, actions <code>gap</code> (4px)</td><td></td></tr></tbody></table><h2 id="token-gaps-and-decisions" tabindex="-1">Token gaps and decisions <a class="header-anchor" href="#token-gaps-and-decisions" aria-label="Permalink to &quot;Token gaps and decisions&quot;">​</a></h2><p>Resolved with the designer 2026-08-25 rather than invented.</p><table tabindex="0"><thead><tr><th>Figma</th><th>Decision</th></tr></thead><tbody><tr><td><code>--ai-font-fixed-6xs</code> (a <strong>font-size</strong> token) bound as the 9px gap between bar and legend, <strong>and</strong> as the legend&#39;s column gap</td><td><strong>Snapped to <code>--ai-spacing-3</code></strong> (8px). A 1px change that stops a type token driving layout. <strong>Figma has since followed</strong> — the bar-to-legend gap now measures 8px there too.</td></tr><tr><td>legend swatch <code>border-radius: 2px</code>, unbound</td><td><strong>New token <code>--ai-radius-xs</code></strong> (2px), created in Figma by the designer. <code>--ai-radius-sm</code> (4px) would visibly round an 8px square. Re-exported and confirmed 2026-08-25 — <code>VariableID:3534:102610</code> in <code>FigmaTokens/Scale/Scale.tokens.json</code>.</td></tr><tr><td>card <code>width: 289px</code></td><td><strong>Dropped.</strong> The card is fluid and fills its grid cell. 289px has no token; the bound <code>min-width</code> does (<code>--ai-size-4</code>).</td></tr><tr><td>sponsor row <code>height: 22px</code></td><td><strong>Dropped as derivable</strong> — it is exactly the 16px icon plus the 6px <code>padding-top</code>, so the content defines it.</td></tr><tr><td><code>line</code> node stroke, invisible in design context</td><td><strong><code>--ai-border-secondary</code></strong>, resolved by calling <code>get_variable_defs</code> on the node itself (<code>3470:85258</code>). Not a gap — just hidden behind an SVG asset.</td></tr></tbody></table><h2 id="the-header-restructure-2026-08-25" tabindex="-1">The header restructure (2026-08-25) <a class="header-anchor" href="#the-header-restructure-2026-08-25" aria-label="Permalink to &quot;The header restructure (2026-08-25)&quot;">​</a></h2><p>The designer rebuilt <code>Header-Section</code> (<code>3476:106256</code>) so a long sponsor name gets the whole card width, and added the title-to-pill clearance that the first build had flagged as missing.</p><table tabindex="0"><thead><tr><th></th><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>Header-Section</code></td><td><strong>row</strong> — title column beside the pill</td><td><strong>column</strong></td></tr><tr><td><code>Title-Label-Group</code></td><td><strong>column</strong> — title above the sponsor row</td><td><strong>row</strong> — title beside the pill</td></tr><tr><td>tier pill</td><td>sibling of the title group, <code>gap: 0</code></td><td><strong>inside the title row, <code>gap: --ai-spacing-4</code></strong> (12px)</td></tr><tr><td>sponsor row</td><td>nested in the title column, <code>88px</code> wide</td><td><strong>full-width sibling below the title row</strong></td></tr><tr><td>frame name</td><td><code>Paragraph</code></td><td><code>Sponsor</code></td></tr><tr><td>table name</td><td><code>white-space: nowrap</code>, no overflow</td><td><strong>no <code>nowrap</code> — it wraps</strong></td></tr></tbody></table><p>Verified: name 198 + 12px gap + pill 36 = the full 246px content width; the sponsor row measures the same 246; a long title wraps to two 20px lines with the pill holding its width on the first line.</p><p><strong>This retires the two divergences the first build carried.</strong> The header gap is now Figma&#39;s own 12px rather than something left at 0 and flagged, and the table name&#39;s ellipsis is gone — Figma dropping <code>nowrap</code> means wrapping is the intended answer to a long name, which is the whole point of the restructure. <code>flex-shrink: 0</code> on the pill is scoped from this row (Figma sets <code>shrink-0</code> on the instance); nothing about TableType&#39;s own appearance is touched.</p><blockquote><p><strong>Only 1 of 12 Figma variants carries this.</strong> <code>3470:85480</code> — the Populated / Default / Desktop variant — is restructured. <code>3470:85479</code>, <code>3472:85601</code> and <code>3484:188923</code> were all checked and still have the old nested header, so the other eleven need the same change in Figma. The CSS applies it to every variant, since it is one shared header.</p></blockquote><h2 id="two-places-the-css-leads-figma" tabindex="-1">Two places the CSS leads Figma <a class="header-anchor" href="#two-places-the-css-leads-figma" aria-label="Permalink to &quot;Two places the CSS leads Figma&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Property</th><th>Figma</th><th>CSS</th></tr></thead><tbody><tr><td><code>__sponsor-name</code></td><td>truncation</td><td><code>white-space: nowrap</code> + <code>shrink-0</code></td><td><strong>+ <code>overflow: hidden</code>, <code>text-overflow: ellipsis</code></strong></td></tr><tr><td><code>__legend-item</code></td><td><code>font-weight</code></td><td><code>--ai-font-regular</code></td><td><strong><code>--ai-font-medium</code></strong></td></tr></tbody></table><p><strong>The sponsor name needs somewhere to stop.</strong> Figma pairs <code>nowrap</code> with <code>shrink-0</code>, which overflows rather than truncating. The full-width row gives a long name far more room than before, but it still needs a limit — verified truncating at 246px.</p><p><strong>The legend is medium</strong>, a designer call 2026-08-25 — at 9px, regular sits too light against the surrounding text. No layout consequence: the legend still measures 24px across two rows and no card height moved.</p><h2 id="a-figma-property-inconsistency-worth-fixing" tabindex="-1">A Figma property inconsistency worth fixing <a class="header-anchor" href="#a-figma-property-inconsistency-worth-fixing" aria-label="Permalink to &quot;A Figma property inconsistency worth fixing&quot;">​</a></h2><p>The three variants expose three different property sets for what is one component:</p><table tabindex="0"><thead><tr><th>Variant</th><th>Properties</th></tr></thead><tbody><tr><td>Populated / Default / Desktop (<code>3470:85480</code>)</td><td><code>Show Sponsor</code> only — and it gates <strong>both</strong> the sponsor row <strong>and</strong> the tier pill</td></tr><tr><td>Populated / Selected / Desktop (<code>3470:85479</code>)</td><td><code>Show Sponsor</code>, <code>Show Table Type</code>, <code>Table Name</code>, plus a <code>Table Type</code> slot</td></tr><tr><td>Populated / Default / Mobile (<code>3484:188923</code>)</td><td><code>Show Sponsor</code>, <code>Table Name</code></td></tr></tbody></table><p>The Default variant tying the tier pill to <code>Show Sponsor</code> is almost certainly an error — a table with no sponsor should still show its tier. The Selected variant models it correctly with a separate <code>Show Table Type</code>. <strong>Built the correct model</strong>: the sponsor row and the tier pill are independently optional. <code>Table Name</code> also exists on some variants and not others, which is why <code>TableCard.figma.ts</code> does <strong>not</strong> use <code>figma.string</code> for it — binding a property that only some variants carry is how the TableType Code Connect went wrong in wave 1.</p><h2 id="cross-component-findings" tabindex="-1">Cross-component findings <a class="header-anchor" href="#cross-component-findings" aria-label="Permalink to &quot;Cross-component findings&quot;">​</a></h2><ul><li><strong>TableType is unchanged, by decision — and the size drift has since closed.</strong> When first built, Figma&#39;s instance rendered at <code>--ai-font-fixed-6xs</code> (9px); as of the header restructure it reads <code>--ai-font-fixed-5xs</code> (10px), matching the component, and the pill grew 34×17 → 36×18 accordingly. Only <code>--ai-tracking-6</code> vs the component&#39;s <code>--ai-tracking-7</code>, and <code>font-semibold</code> vs <code>--ai-font-bold</code>, still differ — the two amends the designer made in wave 1. The call 2026-08-25 was that <strong>the component is the source of truth</strong> and Figma should follow, so nothing was changed. Its colour model was verified correct in passing: Figma&#39;s <code>#b2d5e2</code> border, <code>#005777</code> text and white-80%-over-<code>#00749e</code> fill are exactly what TableType&#39;s three <code>color-mix()</code> formulas produce.</li><li><strong><code>--sp-host</code> is missing from Figma&#39;s legend.</strong> The collection defines it and AttendeeCard uses it, but Table Card&#39;s Figma legend covers only Attendee / VIP / Speaker / Sponsor plus Empty. <strong>Not added here</strong> — inventing a variant with no Figma counterpart is how drift starts. But a table seating a host currently has no colour for them. Since the colour comes from one custom property, adding <code>--host</code> later is a single line. <strong>Worth a designer decision.</strong></li><li><strong>FullBadge was extracted</strong> rather than scoped a second time, because TableCard draws a copy identical to RoomCard&#39;s. See <code>FullBadge.figma-notes.md</code> — including that Figma still has no component for it.</li></ul><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><ul><li><strong>The bar is <code>aria-hidden</code>.</strong> The legend states every role and count as text immediately below it, and the footer states the total — a bare stack of coloured divs adds nothing but noise.</li><li><strong>The action buttons are 24×24</strong>, under the 44×44 minimum in CLAUDE.md §9. Built as drawn, matching the AttendeeCard and RoomCard decisions. The card&#39;s own select target is the full card.</li><li>The FullBadge&#39;s white-on-success contrast (3.16:1) is deliberately open — see its notes.</li><li>The table name is an <code>&lt;h3&gt;</code>; the demo nests it under <code>&lt;h2&gt;</code> section headings.</li></ul><h2 id="where-radius-tokens-actually-live" tabindex="-1">Where radius tokens actually live <a class="header-anchor" href="#where-radius-tokens-actually-live" aria-label="Permalink to &quot;Where radius tokens actually live&quot;">​</a></h2><p>Worth recording, because it cost a wrong guess: the Style Dictionary build reads <code>FigmaTokens/Scale/Scale.tokens.json</code> and <code>FigmaTokens/Semantic/*</code>. The <strong>top-level</strong><code>FigmaTokens/Light.tokens.json</code>, <code>Dark.tokens.json</code> and <code>Primitive.tokens.json</code> are <em>not</em> build sources, despite also containing radius entries — they are legacy files. <code>--ai-radius-xs</code> was briefly hand-added to all three; only the Scale one had any effect, and removing the other two left <code>css/tokens.css</code> byte-identical. <strong>Radius comes from Scale alone.</strong></p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong><code>get_design_context</code> returns the actions frame as an empty <code>&lt;div&gt;</code></strong> on every variant — the two Button instances are flattened out. Only <code>get_metadata</code> on the frame reveals them. The same happened on RoomCard; don&#39;t read that empty div as &quot;no actions&quot;.</li><li><strong>Design context under-reports bound tokens.</strong> The seated count renders as raw <code>text-[12px]</code> and the min-width as <code>min-w-[240px]</code>, but <code>get_variable_defs</code> shows both bound. Always cross-check before flagging a gap.</li><li><strong>The bar segments are named <code>Bar-Staff</code> and <code>Bar-Guest</code></strong> in Figma while the legend beside them says &quot;Attendee&quot; and &quot;Sponsor&quot;. The legend text is what users see, so the CSS uses <code>--attendee</code> and <code>--sponsor</code>. Worth renaming the Figma layers.</li><li><strong>No hover, focus, pressed or disabled variants</strong> exist in the set. The action buttons get Button&#39;s own states; nothing else was invented.</li><li><strong>No dark-mode variant.</strong> Every colour is a theme-aware <code>--ai-*</code> token except the <code>--sp-*</code> role colours, which are <strong>not</strong> theme-aware — so the bar and legend will not adapt under <code>[data-theme=&quot;dark&quot;]</code>. Not designed or reviewed.</li></ul><hr><h2 id="responsive-container-queries-2026-08-27" tabindex="-1">Responsive: container queries (2026-08-27) <a class="header-anchor" href="#responsive-container-queries-2026-08-27" aria-label="Permalink to &quot;Responsive: container queries (2026-08-27)&quot;">​</a></h2><p><strong>Keys on <code>cs-page</code>, NOT a self-container.</strong> Measured own width <strong>275px</strong> on desktop and ~300px on mobile — both under 767, so a self-query would fire on desktop too and the card would permanently wear its mobile padding. The Device=Mobile deltas describe the screen, not the card.</p><p>Rationale and the decision rule live in <strong>CLAUDE.md §4a</strong>. The short version: a docked SidebarMenu shrinks the CC content column with no window resize, so a viewport query cannot see the real available width — measured 820px of column at a 2239px viewport, with no query firing.</p>',60)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
